"use strict";
// Generated by scripts/build-pages.mjs: the pretend AI of the web demo, run in the browser.
(() => {
const STOP = new Set(["the","and","for","you","your","with","what","how","who","does","have","any","are","this","that","data","customer","customers"]);
const stems = (s, min) => new Set((String(s).toLowerCase().match(/[a-z0-9]+/g) || []).filter((w) => w.length >= min && !STOP.has(w)).map((w) => w.replace(/s$/, "")));
function mockMatch(kb, latest) {
  const words = stems(latest, 2);
  let best = null, bestScore = 0;
  for (const c of kb.cards) {
    let s = 0; for (const w of stems(c.keywords, 2)) if (words.has(w)) s++;
    if (s > bestScore) { best = c.id; bestScore = s; }
  }
  const confidence = best ? Math.min(0.95, 0.4 + 0.2 * bestScore) : 0.9;
  return { id: bestScore >= 1 && confidence >= 0.5 ? best : null, best, confidence, covered: bestScore ? 0.8 : 0.1, probabilities: {}, model: "mock" };
}
window.CALL_CUE_STATIC = {
  kbUrl: "kb.json",
  api(p, body, kb) {
    if (p === "/api/match") return mockMatch(kb, body.latest || "");
    if (p === "/api/draft") return { text: "(mock draft) " + (kb.fallback || "Let me check that and confirm in writing.") };
    if (p === "/api/summary") return { text: "(mock summary)\nAsked: " + String(body.transcript || "").split("\n").filter(Boolean).length + " lines\nAnswered: -\nFollow-ups: -" };
    throw new Error("not available in the web demo");
  },
};
})();
